/**
 * The PREVIOUS delivery record for a repair generation = the CHAIN HEAD: the
 * newest record that NO OTHER record supersedes. Chain example:
 *   91cf6d38 -> 646b9cb9 -> <this run>
 * A repair bundle must supersede the CURRENT head（the bundle the external
 * reviewer just returned REPAIR on）— never a stale record. Records with
 * equal timestamps fall back to file-name ordering（deterministic）.
 */
function findLatestDeliveryRecord(outDir) {
  if (!existsSync(outDir)) return null;
  const records = [];
  for (const f of readdirSync(outDir)) {
    if (!/^external-review-delivery-[0-9a-f]{8}\.json$/.test(f)) continue;
    const r = readExternalReviewDeliveryRecord(join(outDir, f));
    if (r.ok) records.push({ fileName: f, ...r });
  }
  if (records.length === 0) return null;
  const supersededIds = new Set(
    records.flatMap((r) => {
      const s = r.state?.supersedes?.reviewBundleIdentity;
      return s ? [s] : [];
    }),
  );
  const heads = records.filter((r) => !supersededIds.has(r.state?.delivery?.reviewBundleIdentity));
  const pool = heads.length > 0 ? heads : records;
  pool.sort((a, b) => {
    const t = String(a.state?.delivery?.attemptedAt ?? "").localeCompare(String(b.state?.delivery?.attemptedAt ?? ""));
    return t !== 0 ? t : a.fileName.localeCompare(b.fileName);
  });
  return pool[pool.length - 1];
}

// Supersede binding from the PREVIOUS delivery record（chain head, if any）.
// The previous record already carries the external REPAIR verdict（the
// receipt for the old bundle）; the new bundle explicitly supersedes it.
let supersedes = null;
{
  const head = findLatestDeliveryRecord(OUT);
  if (head) {
    supersedes = buildSupersedeRecord(head.state);
    console.log(`previous chain head: ${head.state?.delivery?.reviewBundleIdentity} (${head.fileName})`);
  }
}

